begin;
do $$declare t text;begin foreach t in array array['products','product_variants','categories','promotions','site_content','site_settings'] loop execute format('alter table public.%I add column if not exists translations jsonb not null default ''{}''::jsonb check(jsonb_typeof(translations)=''object'')',t);end loop;end$$;
alter table public.promotions add column if not exists label text not null default 'OFERTA ESPECIAL';
alter table public.promotions add column if not exists button_label text not null default '';
alter table public.site_content drop constraint if exists site_content_content_key_check;
alter table public.site_content add constraint site_content_content_key_check check(content_key in ('hero','hero-grill','hero-sea','offer','about'));
create or replace function public.save_product(payload jsonb, variants jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
declare p public.products; v jsonb;
begin
 if not public.is_staff() then raise exception 'Not authorized' using errcode='42501'; end if;
 if jsonb_typeof(variants)<>'array' then raise exception 'Variants must be an array'; end if;
 p=jsonb_populate_record(null::public.products,payload);
 insert into public.products(id,category_id,name,slug,description,ingredients,image_url,image_alt,price,small_price,large_price,price_label,is_available,is_featured,is_visible,sort_order,translations)
 values(p.id,p.category_id,p.name,p.slug,p.description,p.ingredients,p.image_url,p.image_alt,p.price,p.small_price,p.large_price,p.price_label,p.is_available,p.is_featured,p.is_visible,p.sort_order,coalesce(p.translations,'{}'::jsonb))
 on conflict(id) do update set category_id=excluded.category_id,name=excluded.name,slug=excluded.slug,description=excluded.description,ingredients=excluded.ingredients,image_url=excluded.image_url,image_alt=excluded.image_alt,price=excluded.price,small_price=excluded.small_price,large_price=excluded.large_price,price_label=excluded.price_label,is_available=excluded.is_available,is_featured=excluded.is_featured,is_visible=excluded.is_visible,sort_order=excluded.sort_order,translations=excluded.translations;
 delete from public.product_variants where product_id=p.id;
 for v in select * from jsonb_array_elements(variants) loop
 insert into public.product_variants(id,product_id,name,price,sort_order,is_available,is_addon,translations) values(coalesce((v->>'id')::uuid,gen_random_uuid()),p.id,v->>'name',(v->>'price')::numeric,coalesce((v->>'sort_order')::integer,0),coalesce((v->>'is_available')::boolean,true),coalesce((v->>'is_addon')::boolean,false),coalesce(v->'translations','{}'::jsonb));
 end loop;
 return p.id;
end $$;
revoke all on function public.save_product(jsonb,jsonb) from public;
grant execute on function public.save_product(jsonb,jsonb) to authenticated;
commit;
-- Secciones iniciales del carrusel y banner, sin ofertas inventadas.
begin;
insert into public.site_content(id,content_key,title,subtitle,body,image_url,image_alt,button_label,button_url,metadata,is_visible,translations) values('30000000-0000-4000-8000-000000000001','hero','Pizzas a la piedra','DIEGUITO · USHUAIA','Sabores irresistibles, ingredientes seleccionados y ese toque casero que nos caracteriza.','/images/hero/pizza.png','Pizza artesanal a la piedra','Ver pizzas','/#menu-pizzas','{"category_slug":"pizzas","sort_order":0}'::jsonb,true,'{"pt":{"title":"Pizzas na pedra","body":"Sabores irresistíveis, ingredientes selecionados e aquele toque caseiro que nos caracteriza.","button_label":"Ver pizzas","image_alt":"Pizza artesanal assada na pedra"},"en":{"title":"Stone-baked pizzas","body":"Irresistible flavors, selected ingredients and our signature homemade touch.","button_label":"View pizzas","image_alt":"Artisan stone-baked pizza"}}'::jsonb) on conflict(content_key) do update set title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,image_url=excluded.image_url,image_alt=excluded.image_alt,button_label=excluded.button_label,button_url=excluded.button_url,metadata=excluded.metadata,is_visible=excluded.is_visible,translations=excluded.translations where public.site_content.title='El sabor de Ushuaia';
insert into public.site_content(id,content_key,title,subtitle,body,image_url,image_alt,button_label,button_url,metadata,is_visible,translations) values('30000000-0000-4000-8000-000000000003','hero-grill','El sabor de nuestra parrilla','DIEGUITO · USHUAIA','Carnes, cordero y platos preparados para disfrutar en Ushuaia.','/images/hero/parrilla.png','Parrillada de carne y cordero','Ver parrillada','/#menu-parrillada','{"category_slug":"parrillada","sort_order":1}'::jsonb,true,'{"pt":{"title":"O sabor do nosso churrasco","body":"Carnes, cordeiro e pratos preparados para saborear em Ushuaia.","button_label":"Ver churrasco","image_alt":"Churrasco de carne e cordeiro"},"en":{"title":"The flavor of our grill","body":"Beef, lamb and dishes made to enjoy in Ushuaia.","button_label":"View grill","image_alt":"Grilled beef and lamb"}}'::jsonb) on conflict(content_key) do update set title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,image_url=excluded.image_url,image_alt=excluded.image_alt,button_label=excluded.button_label,button_url=excluded.button_url,metadata=excluded.metadata,is_visible=excluded.is_visible,translations=excluded.translations where public.site_content.title='El sabor de Ushuaia';
insert into public.site_content(id,content_key,title,subtitle,body,image_url,image_alt,button_label,button_url,metadata,is_visible,translations) values('30000000-0000-4000-8000-000000000004','hero-sea','Sabores del fin del mundo','DIEGUITO · USHUAIA','Centolla, merluza negra, salmón y especialidades del mar.','/images/hero/mar.png','Salmón y centolla en un plato','Ver platos del mar','/#menu-del-mar','{"category_slug":"del-mar","sort_order":2}'::jsonb,true,'{"pt":{"title":"Sabores do fim do mundo","body":"Centolla, merluza negra, salmão e especialidades do mar.","button_label":"Ver pratos do mar","image_alt":"Salmão e centolla em um prato"},"en":{"title":"Flavors from the end of the world","body":"King crab, Patagonian toothfish, salmon and seafood specialties.","button_label":"View seafood","image_alt":"Salmon and king crab on a plate"}}'::jsonb) on conflict(content_key) do update set title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,image_url=excluded.image_url,image_alt=excluded.image_alt,button_label=excluded.button_label,button_url=excluded.button_url,metadata=excluded.metadata,is_visible=excluded.is_visible,translations=excluded.translations where public.site_content.title='El sabor de Ushuaia';
insert into public.site_content(id,content_key,title,subtitle,body,image_url,image_alt,button_label,button_url,metadata,is_visible,translations) values('30000000-0000-4000-8000-000000000005','offer','Consultá nuestras promociones','OFERTA ESPECIAL','Descubrí las promociones disponibles de esta semana.','/images/hero/pizza.png','Pizza artesanal','Ver promociones','/#promociones','{}'::jsonb,true,'{"pt":{"title":"Confira nossas promoções","subtitle":"OFERTA ESPECIAL","body":"Descubra as promoções disponíveis nesta semana.","button_label":"Ver promoções","image_alt":"Pizza artesanal"},"en":{"title":"Ask about our promotions","subtitle":"SPECIAL OFFER","body":"Discover this week''s available promotions.","button_label":"View promotions","image_alt":"Artisan pizza"}}'::jsonb) on conflict(content_key) do update set title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,image_url=excluded.image_url,image_alt=excluded.image_alt,button_label=excluded.button_label,button_url=excluded.button_url,metadata=excluded.metadata,is_visible=excluded.is_visible,translations=excluded.translations where public.site_content.title='El sabor de Ushuaia';
